// ÉCLAIREUR — extraction du texte lisible d'une page HTML
const MAX_CHARS = 2500;
const src = $('Webhook').first().json || {};
const body = src.body || {};
const url = String(body.url || '').trim();
const question = String(body.question || '').trim();

const erreur = (msg) => [{ json: { erreur: msg, url, question } }];

if (!url || !/^https?:\/\//i.test(url)) {
  return erreur('URL manquante ou non http(s)');
}

const item = $input.first().json || {};
if (item.error) {
  const msg = typeof item.error === 'string' ? item.error : (item.error.message || 'échec de la requête HTTP');
  return erreur('Impossible de lire la page : ' + msg);
}
const status = item.statusCode || 0;
const html = typeof item.body === 'string' ? item.body : (typeof item.data === 'string' ? item.data : '');

if (status < 200 || status >= 300) {
  return erreur('La page a répondu HTTP ' + status);
}
if (!html) {
  return erreur('Réponse vide (aucun contenu HTML)');
}

let t = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<(br|\/p|\/div|\/h[1-6]|\/li|\/tr|\/table|\/section|\/article)[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' ');

// Entités HTML nommées (les plus courantes, accentuées FR incluses)
const ents = {
  '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'",
  '&apos;': "'", '&nbsp;': ' ', '&eacute;': 'é', '&egrave;': 'è',
  '&agrave;': 'à', '&ccedil;': 'ç', '&ecirc;': 'ê', '&ocirc;': 'ô',
  '&ucirc;': 'û', '&uuml;': 'ü', '&auml;': 'ä', '&ouml;': 'ö',
  '&iuml;': 'ï', '&szlig;': 'ß', '&euro;': '€', '&laquo;': '«', '&raquo;': '»'
};
t = t.replace(/&(amp|lt|gt|quot|#39|apos|nbsp|eacute|egrave|agrave|ccedil|ecirc|ocirc|ucirc|uuml|auml|ouml|iuml|szlig|euro|laquo|raquo);/g,
  (m) => ents[m] ?? m);
t = t.replace(/&#(\d+);/g, (_, d) => { try { return String.fromCodePoint(+d); } catch { return ' '; } });
t = t.replace(/&#x([0-9a-f]+);/gi, (_, h) => { try { return String.fromCodePoint(parseInt(h, 16)); } catch { return ' '; } });

// Nettoyage des espaces / lignes vides
t = t
  .split('\n')
  .map((l) => l.replace(/[ \t]+/g, ' ').trim())
  .filter(Boolean)
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!t) {
  return erreur('Aucun texte extrait de la page');
}
if (t.length > MAX_CHARS) {
  t = t.slice(0, MAX_CHARS) + '\n\n[… texte tronqué]';
}

return [{ json: { url, question, texte: t, longueur: t.length, statusCode: status } }];

// ÉCLAIREUR — préparation de la requête /api/chat pour Ollama
const item = $input.first().json || {};
const { url, question, texte } = item;

const system =
  "Tu es ÉCLAIREUR, un assistant de lecture de pages web. " +
  "On te fournit le TEXTE D'UNE PAGE WEB (extrait, possiblement tronqué). " +
  "Réponds en français, uniquement à partir de ce texte, sans inventer. Reste bref : résumé en 5 phrases maximum, réponse directe et courte pour une question. " +
  "Si l'information demandée n'est pas dans le texte, dis-le clairement. " +
  "Sois concis et structuré (phrases courtes, listes si utile).";

const consigne = question
  ? "Voici une page web et une question. Réponds à la question en te basant sur la page.\n\nQUESTION : " + question
  : "Voici une page web. Fais-en un résumé clair et concis (l'essentiel, les points clés), en français.";

const user = consigne + "\n\nPAGE : " + url + "\n\nTEXTE DE LA PAGE :\n" + texte;

const payload = {
  model: 'qwen2.5:3b',
  stream: false,
  keep_alive: 0, // décharge immédiat : usage à la demande, pas de RAM résidente
  options: { num_ctx: 8192, temperature: 0.3, num_predict: 350 },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user }
  ]
};

return [{ json: { ollama_body: JSON.stringify(payload), url, question } }];
